<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {api,type BackupRecord} from '../api'
const props=defineProps<{busy:boolean}>()
const emit=defineEmits<{load:[id:string];relocate:[id:string];view:[id:string];remove:[ids:string[]];forget:[id:string];check:[id:string];clean:[ids:string[]];cleanResults:[jobID:string]}>()
const refreshing=ref(false)
const rows=ref<BackupRecord[]>([]),checked=ref<string[]>([]),error=ref(''),confirming=ref(false)
const forgetting=ref<BackupRecord|null>(null)
const canForget=(row:BackupRecord)=>row.status==='deleted'&&row.local_state==='missing'
const selectedRecords=computed(()=>rows.value.filter(r=>checked.value.includes(r.id)))
const selected=computed(()=>selectedRecords.value.filter(r=>r.status!=='deleted'||r.local_state==='present'||r.local_state==='pending'))
const cleanable=computed(()=>selectedRecords.value.filter(r=>r.files>0))
const selectedBytes=computed(()=>selected.value.reduce((sum:number,row:BackupRecord)=>sum+row.bytes,0))
const localLabels:Record<string,string>={present:'本地位置存在（内容未校验）',missing:'登记位置未找到',unavailable:'位置暂不可访问，状态未知',changed:'位置对象类型已变化',pending:'删除暂存待处理'}
const labels:Record<string,string>={available:'本地位置已登记',deleted:'登记位置已确认清理',deleting:'本地包删除中 / 待继续',delete_failed:'本地包删除未完成',unavailable:'本地位置不可用'}
const fileLabels:Record<string,string>={present:'原路径全部存在（内容未校验）',missing:'原路径全部未找到',partial:'部分存在或大小变化',unknown:'部分或全部无法核对',unlinked:'未关联本机原来源',empty:'无已备份原文件'}
const restoreLabels:Record<string,string>={running:'正在恢复',completed:'已补回目标媒体目录',qman_only:'已保存到 Qman 独立库',fallback:'部分或全部回退到 Qman',partial:'部分完成，需查看结果',failed:'恢复失败',cancelled:'已取消，可能保留部分文件',interrupted:'上次恢复中断，结果待核对',legacy:'已有加载记录（待查看旧结果）',recorded:'已有旧加载结果'}
const fmtTime=(value?:string)=>value&&!value.startsWith('0001-')?new Date(value).toLocaleString():'时间未知'
function packageLabel(row:BackupRecord){if(row.local_state==='missing'&&row.status==='deleted')return '已确认清理，当前位置无备份包';if(row.local_state==='present'&&row.status==='deleted')return '位置重新出现（内容未校验）';return localLabels[row.local_state??'']||'位置待核对'}
function cleanupLabel(row:BackupRecord){const result=row.cleanup_result;if(!result)return row.source_cleanup_job?'已有清理记录（旧记录）':'尚未清理';if(result.state==='prepared')return '已预检，待确认';if(result.state==='preparing')return '正在预检';if(result.state==='running')return '正在回收';if(result.state==='interrupted')return '清理中断，未自动继续';if(result.failed||result.uncertain||result.remaining)return '清理未全部完成';if(result.skipped)return result.recycled?'已回收部分，其余跳过':'未回收，所选项已跳过';return result.recycled?'回收完成':'任务结束，未回收文件'}
function tone(state?:string){return ['completed','qman_only','present'].includes(state??'')?'success':['failed','changed'].includes(state??'')?'error':['unknown','partial','fallback','interrupted','cancelled','pending','delete_failed'].includes(state??'')?'warning':'muted'}
const bytes=(v:number)=>`${(v/1024/1024).toLocaleString(undefined,{maximumFractionDigits:1})} MiB`
function scope(r:BackupRecord){const f=r.selection;const names:Record<string,string>={image:'图片',video:'视频',emoji:'收到的表情',voice:'语音'};return `${names[f.kind]||'全部类型'} · ${f.month_from||f.month_to?`${f.month_from||'不限'} 至 ${f.month_to||'不限'}`:f.month||'全部月份'}${f.view==='observed'?' · 发现日期视图':''}${f.from||f.to?` · ${f.from||'不限'} 至 ${f.to||'不限'}`:''}`}
let loading=false,disposed=false
async function refresh(){if(loading||disposed)return;loading=true;refreshing.value=true;try{const result=await api().GetBackupHistory();if(!disposed){rows.value=result;error.value=''}}catch(e){if(!disposed)error.value=String(e)}finally{loading=false;refreshing.value=false}}
function toggleAll(event:Event){checked.value=(event.target as HTMLInputElement).checked?rows.value.slice(0,100).map(r=>r.id):[]}
function remove(){const ids=selected.value.map(r=>r.id);confirming.value=false;checked.value=[];emit('remove',ids)}
function clean(){const ids=cleanable.value.map(r=>r.id);checked.value=[];emit('clean',ids)}
function forget(){const row=forgetting.value;if(!row||props.busy)return;forgetting.value=null;checked.value=checked.value.filter(id=>id!==row.id);emit('forget',row.id)}
watch(()=>props.busy,(current,previous)=>{if(previous&&!current)void refresh()})
function focusRefresh(){if(!props.busy)void refresh()}
onMounted(()=>{void refresh();window.addEventListener('focus',focusRefresh) });onUnmounted(()=>{disposed=true;window.removeEventListener('focus',focusRefresh)})
</script>
<template>
<section class="backup-history">
 <div class="history-toolbar"><div><h1>备份历史</h1><p>备份包位置在打开、重新聚焦或刷新时检查。本地原文件按单份清单核对，显示核对时间；清理和恢复结果独立保留。</p></div><div class="history-batch-actions"><button class="secondary" :disabled="busy||refreshing" @click="refresh">{{refreshing?'正在检查位置…':'刷新本地状态'}}</button><button class="danger-button" :disabled="busy||!cleanable.length||cleanable.length>100" @click="clean">清理选中备份的原文件（{{cleanable.length}}）</button><button class="danger-button" :disabled="busy||!selected.length||selected.length>100" @click="confirming=true">删除本地备份包（{{selected.length}}）</button></div></div>
 <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="!rows.length" class="ready-note">暂无备份记录。创建备份或通过“加载备份”选择已有备份后，会在这里登记。</p>
 <div v-else class="history-table-wrap"><table class="history-table"><thead><tr><th><input type="checkbox" aria-label="选择最多一百份备份记录" :disabled="busy" @change="toggleAll"/></th><th>备份范围 / 位置</th><th>文件状态 / 操作结果</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><input type="checkbox" :value="row.id" v-model="checked" :disabled="busy" :aria-label="`选择备份 ${row.name}`"/></td><td><strong>{{row.name}} · {{scope(row)}}</strong><p class="path-text">{{row.path}}</p><small>{{row.format==='zip'?'ZIP 文件':'文件夹'}} · {{row.files}} 个媒体引用（创建时记录）</small><p>{{new Date(row.created_at).toLocaleString()}}<br/>{{bytes(row.bytes)}}（登记大小）</p></td><td class="backup-status-cell"><div class="backup-status-grid">
 <div class="backup-status-block"><strong>备份包</strong><span class="status-badge" :class="tone(row.local_state)">{{packageLabel(row)}}</span><small v-if="row.location_checked_at">位置检查：{{fmtTime(row.location_checked_at)}}</small><span v-if="row.status==='delete_failed'" class="status-badge error">删除未完成</span></div>
 <div class="backup-status-block"><strong>本地原文件</strong><span class="status-badge" :class="tone(row.original_files?.stale?'unknown':row.original_files?.state)">{{row.original_files?.stale?'操作后需重新核对':row.original_files?(fileLabels[row.original_files.state]||'状态待核对'):'尚未核对原路径'}}</span><template v-if="row.original_files"><small>上次核对：{{fmtTime(row.original_files.checked_at)}}</small><span>存在 {{row.original_files.present}} · 未找到 {{row.original_files.missing}} · 大小/类型变化 {{row.original_files.changed}} · 未知 {{row.original_files.unknown}}</span></template><small>仅路径/大小检查，外部变化后需重查。</small></div>
 <div class="backup-status-block"><strong>原文件清理结果</strong><span class="status-badge" :class="tone(row.cleanup_result?.state==='completed'&&(row.cleanup_result.skipped||row.cleanup_result.failed||row.cleanup_result.uncertain||row.cleanup_result.remaining)?'partial':row.cleanup_result?.state)">{{cleanupLabel(row)}}</span><template v-if="row.cleanup_result"><small>{{row.cleanup_result.joint?'联合任务 · ':''}}状态更新：{{fmtTime(row.cleanup_result.at)}}</small><span>回收 {{row.cleanup_result.recycled}} · 跳过 {{row.cleanup_result.skipped}} · 失败 {{row.cleanup_result.failed}} · 待核对 {{row.cleanup_result.uncertain}} · 未处理 {{row.cleanup_result.remaining}}</span></template><small v-else-if="row.source_cleanup_detail">{{row.source_cleanup_detail}}</small></div>
 <div class="backup-status-block"><strong>最近恢复结果</strong><span class="status-badge" :class="tone(row.restore_result?.state)">{{row.restore_result?(restoreLabels[row.restore_result.state]||'结果待核对'):'尚未加载备份'}}</span><template v-if="row.restore_result"><small>{{fmtTime(row.restore_result.finished_at||row.restore_result.started_at)}}</small><span v-if="row.restore_result.state!=='legacy'">补回 {{row.restore_result.written}} · 相同跳过 {{row.restore_result.skipped}} · 冲突另存 {{row.restore_result.conflicts}} · 仅 Qman {{row.restore_result.fallback}} · 未完成 {{row.restore_result.failed}}</span><small v-if="row.restore_result.target" class="path-text">请求目标：{{row.restore_result.target}}</small><small v-if="row.restore_result.detail">{{row.restore_result.detail}}</small></template><small>操作记录，不证明当前存在或 QQ 已识别。</small></div>
 </div><details><summary>操作详情</summary><p>{{row.local_detail}}</p><p>{{labels[row.status]||row.status}} · {{row.detail}}</p><p>{{row.source_cleanup_detail}}</p></details>
</td><td><div class="history-row-actions"><button class="secondary" :disabled="busy" @click="emit('check',row.id)">核对原文件</button><button class="secondary" :disabled="busy||!row.files" @click="emit('clean',[row.id])">清理对应原文件</button><button v-if="row.source_cleanup_job" class="text-button" :disabled="busy" @click="emit('cleanResults',row.source_cleanup_job)">查看原文件清理结果</button><button class="secondary" :disabled="busy||row.status==='deleting'||row.local_state==='missing'||row.local_state==='unavailable'||row.local_state==='pending'" @click="emit('load',row.id)">加载备份</button><button class="secondary" :disabled="busy" @click="emit('relocate',row.id)">重新定位</button><button class="text-button" :disabled="busy" @click="emit('view',row.id)">查看已加载媒体</button><button class="text-button" :disabled="busy||!canForget(row)" :title="canForget(row)?'删除这条备份历史记录':'先删除本地备份包，并确认登记位置已不存在后可用'" @click="forgetting=row">删除历史记录</button></div></td></tr></tbody></table></div>
 <div v-if="confirming" class="modal-backdrop" @click.self="confirming=false"><section class="backup-modal" role="dialog" aria-modal="true" aria-label="确认批量删除本地备份包"><h2>永久删除 {{selected.length}} 份本地备份包？</h2><p>所选记录原登记大小 {{bytes(selectedBytes)}}，不代表当前实际大小。登记位置已不存在的项目只确认本地状态，不再执行磁盘删除；位置可能已改名或移动，程序不搜索其他目录。仍存在的包会在执行前重新校验。此操作不清理原文件或独立副本，不经过回收站；请确认仍保有需要的备份。历史清单继续保留，已清理且未重新出现的位置不重复处理；历史和原文件关联继续保留。</p><ul class="delete-review"><li v-for="row in selected" :key="row.id">{{row.name}}<span class="path-text">{{row.path}}</span></li></ul><div class="modal-actions"><button class="secondary" @click="confirming=false">取消</button><button class="danger-button" :disabled="props.busy" @click="remove">永久删除这些本地备份包</button></div></section></div>
 <div v-if="forgetting" class="modal-backdrop" @click.self="forgetting=null"><section class="backup-modal" role="dialog" aria-modal="true" aria-label="确认删除备份历史记录"><h2>删除这条备份历史记录？</h2><p><strong>{{forgetting.name}} · {{scope(forgetting)}}</strong></p><p class="path-text">{{forgetting.path}}</p><p>将移除这条备份记录、保存的备份清单及其原文件关联，之后无法从此记录“清理对应原文件”或重新定位。关联但尚未执行的原文件清理确认会失效，需要重新预检。</p><p>原文件、已加载的媒体副本及独立保存的加载记录、原文件清理结果会保留。此操作无法撤销；如果仍保有完整备份包，可通过“加载备份”重新登记。</p><div class="modal-actions"><button class="secondary" :disabled="busy" @click="forgetting=null">取消</button><button class="danger-button" :disabled="busy" @click="forget">删除这条历史记录</button></div></section></div>
</section>
</template>
